contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    // params: target address to freeze/unfreeze, the boolean freeze value
    function run(address target, bool freeze) public payable {
        require(target != address(0)); // avoid zero-address ambiguity

        // The test contract deployed c, so this contract is the owner and can call onlyOwner functions.
        // Record the frozen flag before the call using the public getter.
        bool beforeFlag = c.frozenAccount(target); if (__ESBMC_reverted()) return;

        // Attempt to call freezeAccount and record whether it reverted.
        bool didRevert;
        c.freezeAccount(target, freeze); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // Read the observable frozen flag after the call.
        bool afterFlag = c.frozenAccount(target); if (__ESBMC_reverted()) return;

        // If the call reverted then the flag must be unchanged; otherwise it must equal the provided value.
        assert(didRevert ? (afterFlag == beforeFlag) : (afterFlag == freeze));
    }

    receive() external payable { }
}

